import { readFileSync } from 'node:fs';
// Runtime roster audit: drives the game's real character select through every launch fighter and
// verifies that the body the fighter is exported with - public/models/characters/roster/<slug>.glb,
// generated by assets/blender/build_roster_fighters.py - is what ends up on the live fighter, with
// a bound skeleton, the canonical joint names the rest of the game reads, its weapon and a
// structurally valid rig. Static validation can prove the files exist; only the browser can prove
// the selection path mounts them.
import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { resolve, normalize, sep, extname } from 'node:path';
import { chromium } from 'playwright';

/** The joint names a mounted body has to answer to, whatever skeleton it ships. */
const JOINT_NAMES = ['pelvis', 'torso', 'head', 'leftArm', 'rightArm', 'leftFore', 'rightFore',
  'leftLeg', 'rightLeg', 'leftShin', 'rightShin'];

const root = process.cwd();
const mime = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.glb': 'model/gltf-binary',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.webp': 'image/webp',
  '.svg': 'image/svg+xml'
};

async function serveThreeLocally(page) {
  await page.route('https://unpkg.com/three@0.152.2/**', async requestRoute => {
    const requestUrl = new URL(requestRoute.request().url());
    const relative = requestUrl.pathname.replace('/three@0.152.2/', '');
    try {
      const body = await readFile(resolve(root, 'node_modules/three', relative));
      await requestRoute.fulfill({ status: 200, contentType: 'text/javascript; charset=utf-8', headers: { 'Access-Control-Allow-Origin': '*' }, body });
    } catch {
      await requestRoute.fulfill({ status: 404, contentType: 'text/plain', body: 'missing ' + relative });
    }
  });
}

const server = createServer(async (req, res) => {
  try {
    const pathname = decodeURIComponent(new URL(req.url || '/', 'http://localhost').pathname);
    let relative = normalize(pathname).replace(/^[/\\]+/, '') || 'index.html';
    if (['js', 'assets', 'models'].some(dir => relative === dir || relative.startsWith(dir + sep))) relative = 'public' + sep + relative;
    const filePath = resolve(root, relative);
    if (filePath !== root && !filePath.startsWith(root + sep)) { res.writeHead(403); res.end('Forbidden'); return; }
    const bytes = await readFile(filePath);
    res.writeHead(200, { 'Content-Type': mime[extname(filePath).toLowerCase()] || 'application/octet-stream', 'Cache-Control': 'public, max-age=3600' });
    res.end(bytes);
  } catch {
    res.writeHead(404, { 'Content-Type': 'text/plain' });
    res.end('Not found');
  }
});
await new Promise(resolveListen => server.listen(0, '127.0.0.1', resolveListen));
const origin = 'http://127.0.0.1:' + server.address().port;

let browser;
try {
  browser = await chromium.launch({
    headless: true,
    args: ['--no-sandbox', '--enable-webgl', '--ignore-gpu-blocklist', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader']
  });
  const page = await browser.newPage({ viewport: { width: 640, height: 400 } });
  const pageErrors = [];
  page.on('pageerror', error => pageErrors.push(error.message));
  await serveThreeLocally(page);
  await page.goto(origin + '/public/index.html', { waitUntil: 'domcontentloaded', timeout: 60_000 });
  await page.waitForFunction(() => {
    const state = window.__browserSmashAssets || {};
    return state.characters?.status === 'loaded' && state.weapons?.status === 'loaded'
      && Object.keys(state.characterModels || {}).length > 0
      && window.fighters?.length === 2;
  }, null, { timeout: 180_000, polling: 250 });

  const libraries = await page.evaluate(() => ({
    characters: window.__browserSmashAssets.characters.count,
    prefabs: window.__browserSmashAssets.characters.keys || [],
    weapons: window.__browserSmashAssets.weapons.count,
    roster: window.characterRosters?.launch?.map(([name]) => name) || []
  }));
  assert.ok(libraries.characters >= 57, 'character prefab library is incomplete: ' + libraries.characters);
  assert.ok(libraries.weapons >= 68, 'weapon prefab library is incomplete: ' + libraries.weapons);
  assert.ok(libraries.roster.length >= 32, 'launch roster is missing from the page');

  const slugOf = name => String(name).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  const failures = [];
  const rows = [];
  const prefabKeys = new Set(libraries.prefabs);
  // Informational: identities the primitive library has no prefab for. They used to fall back to
  // the procedural body; every one of them now has an exported body of its own.
  const withoutPrefab = libraries.roster.filter(name => !prefabKeys.has('character_' + slugOf(name)));

  for (const name of libraries.roster) {
    const slug = slugOf(name);
    const mounted = await page.evaluate(async ({ fighterName, expectedSlug }) => {
      const joints = ['pelvis', 'torso', 'head', 'leftArm', 'rightArm', 'leftFore', 'rightFore',
        'leftLeg', 'rightLeg', 'leftShin', 'rightShin'];
      const select = document.querySelector('#p1Character');
      select.value = fighterName;
      select.dispatchEvent(new Event('change'));
      const fighter = window.fighters[0];
      // Selecting mounts two bodies: the prefab library body first, then the fighter's own
      // exported GLB, then the weapon on the new body. Judge what is on screen once the
      // character body has landed, not the intermediate body or a timeout.
      const deadline = Date.now() + 30000;
      let model = fighter.model;
      while (Date.now() < deadline) {
        model = fighter.model;
        const asset = model?.userData?.characterAssetUrl;
        // Any character body (generated roster export or an imported model in its own directory)
        // has landed; which file it is is asserted below by ownAsset(), not by this wait. The old
        // /roster/ check stalled the full 30 s on every imported body.
        if (fighter.identity === fighterName && asset) break;
        await new Promise(done => setTimeout(done, 50));
      }
      const rig = window.__browserSmashRigCheck?.(fighter) || { ok: false, issues: ['rig check hook missing'], metrics: {} };
      let visibleMeshes = 0;
      model?.traverse(node => { if (node.isMesh && node.visible) visibleMeshes++; });
      const asset = model?.userData?.characterAssetUrl || null;
      const body = model?.userData?.sculptedBody ? 'sculpted' : asset ? 'imported' : 'procedural';
      return {
        body,
        asset,
        model: model?.name || null,
        rigInfo: rig.rig || null,
        weapon: model?.userData?.weaponLabel || null,
        kind: model?.userData?.weaponKind || null,
        detail: Object.keys(model?.userData?.surfaceDetail || {}),
        visibleMeshes,
        rigOk: rig.ok,
        rigIssues: rig.issues,
        height: rig.metrics?.height ?? null,
        feetY: rig.metrics?.feetY ?? null,
        headAbovePelvis: rig.metrics?.headAbovePelvis ?? null,
        renderable: rig.metrics?.renderableMeshes ?? 0,
        joints: joints.filter(joint => model?.userData?.[joint])
      };
    }, { fighterName: name, expectedSlug: slug });

    if (mounted.body !== 'imported') {
      failures.push({ name, ...mounted, error: 'the fighter is not on the body exported for it' });
    } else if (!mounted.rigOk || mounted.visibleMeshes === 0 || mounted.renderable === 0) {
      failures.push({ name, ...mounted, error: 'mounted rig is not structurally valid' });
    } else rows.push({ name, ...mounted });
    process.stdout.write(`\r${rows.length + failures.length}/${libraries.roster.length} fighters audited`);
  }
  process.stdout.write('\n');

  const withoutDetail = rows.filter(row => row.detail.length === 0);
  const heights = rows.map(row => row.height).filter(value => typeof value === 'number');
  const feet = rows.map(row => row.feetY).filter(value => typeof value === 'number');
  const unarmed = rows.filter(row => row.kind === 'unarmed');
  console.log(JSON.stringify({
    audit: failures.length === 0 ? 'pass' : 'fail',
    prefabs: libraries.characters,
    weapons: libraries.weapons,
    selectable: libraries.roster.length,
    mounted: rows.length,
    // Kept for continuity with earlier reports: the primitive-prefab body is no longer the body
    // any selectable fighter ships, so this is 0 by design and proceduralFallback is now only the
    // list of identities the primitive library has no entry for.
    prefabBacked: rows.filter(row => row.body === 'prefab').length,
    proceduralFallback: withoutPrefab,
    rosterBacked: rows.filter(row => row.body === 'imported').length,
    canonicalJointsBound: rows.filter(row => row.joints.length === JOINT_NAMES.length).length,
    resolvedSkeletons: rows.filter(row => row.rigInfo?.kind === 'bone' && !(row.rigInfo?.missing || []).length).length,
    weaponed: rows.length - unarmed.length,
    unarmed: unarmed.map(row => row.name),
    withSurfaceDetail: rows.length - withoutDetail.length,
    heightRange: heights.length ? [Math.min(...heights), Math.max(...heights)] : null,
    worstGroundOffset: feet.length ? Math.max(...feet.map(value => Math.abs(value))) : null,
    pageErrors: pageErrors.length,
    failures,
    detailClasses: [...new Set(rows.flatMap(row => row.detail))].sort()
  }, null, 2));
  assert.deepEqual(failures, [], 'fighters failed to mount or failed rig validation: ' + JSON.stringify(failures, null, 2));

  // Every selectable fighter must be on the body exported for it. This replaces the old "at least
  // 30 fighters mounted a prefab" guard with a stronger one: a new identity cannot quietly reuse
  // another fighter's body, fall back to the primitive procedural body, or lose its exported body
  // in a regression - and every fighter is checked, not a pinned list of exceptions.
  assert.equal(rows.length, libraries.roster.length,
    'the audit did not reach every selectable fighter: ' + rows.length + ' of ' + libraries.roster.length);
  assert.deepEqual(rows.filter(row => row.body !== 'imported').map(row => ({ name: row.name, body: row.body, asset: row.asset })),
    [], 'a selectable fighter is not on its own exported body');
  // A fighter's own export: roster/<slug>.glb for the generated roster, or <slug>/<slug>.glb for a
  // body that was authored into its own directory - Kaze, the reference fighter the roster kernel
  // was taken from, is exported to public/models/characters/kaze/.
  // A body may be authored under an imported key (e.g. Infantry -> roster_hd/infantry_cc0.glb).
  // The manifest is the authority for which file a selectable identity owns.
  const declaredRosterBodies = JSON.parse(readFileSync('public/models/characters/manifest.json','utf8')).characters || {};
  const ownAsset = row => {
    const file = String(row.asset || '').split('?')[0];
    const slug = slugOf(row.name);
    const declared = declaredRosterBodies?.[slug]?.url;
    if (declared && file.endsWith(String(declared).split('?')[0])) return true;
    return file.endsWith('/roster/' + slug + '.glb') || file.endsWith('/' + slug + '/' + slug + '.glb');
  };
  const wrongAsset = rows.filter(row => !ownAsset(row));
  assert.deepEqual(wrongAsset.map(row => ({ name: row.name, asset: row.asset })), [],
    'a fighter mounted another character\'s body file');
  assert.equal(new Set(rows.map(row => row.asset)).size, rows.length,
    'two selectable fighters mounted the same body file');
  const jointless = rows.filter(row => row.joints.length !== JOINT_NAMES.length);
  assert.deepEqual(jointless.map(row => ({ name: row.name, joints: row.joints })), [],
    'a mounted body does not answer to the canonical joint names the weapon mount and the rig gate read');
  const skeletalless = rows.filter(row => row.rigInfo?.kind !== 'bone' || (row.rigInfo?.missing || []).length);
  assert.deepEqual(skeletalless.map(row => ({ name: row.name, rig: row.rigInfo })), [],
    'a mounted body has no fully resolved skeleton');
  // A fighter is armed with its signature weapon or unarmed by design (the three hand-attack
  // identities). A body that reports neither lost its weapon in the swap.
  assert.ok(rows.every(row => row.weapon), 'every fighter must report a weapon or an unarmed strike');
  assert.ok(rows.every(row => row.visibleMeshes > 0), 'every mounted fighter must have visible meshes');
  assert.ok(rows.every(row => Math.abs(row.feetY) <= 0.2), 'every mounted fighter must stand on its own origin');
  // The generated weave/brushed/grain detail has to land on the body that ships. It used to be
  // applied only to the prefab body that the fighter's own exports replace a frame later, which
  // left all 34 fighters rendering as smooth flat plastic under their real bodies.
  assert.deepEqual(withoutDetail.map(row => ({ name: row.name, detail: row.detail })), [],
    'a mounted fighter body has no generated surface detail');
  assert.ok(rows.every(row => row.headAbovePelvis >= 0.35), 'every mounted fighter must have its head above its pelvis');
  assert.deepEqual(pageErrors, [], 'page raised runtime errors: ' + pageErrors.join('\n'));
  console.log('Roster audit passed: all ' + rows.length + ' selectable fighters mounted the body exported for them ('
    + (rows.length - unarmed.length) + ' carrying their signature weapon, ' + unarmed.length + ' unarmed by design).');
} finally {
  if (browser) await browser.close();
  await new Promise(resolveClose => server.close(resolveClose));
}
